 $('#font-toggle').onclick=()=>{state.font=!state.font;document.body.classList.toggle('large-type',state.font);save();};$('#theme-toggle').onclick=()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);save();};
 function openRouteQuestion(){const p=route().params;if(byId.has(p.get('question'))){openQuestion(p.get('question'),undefined,true);if(p.get('focus')==='methods')revealSection('#question-methods');}}
 window.addEventListener('hashchange',()=>{$$('details.top-more[open],details.site-more[open]').forEach(d=>d.open=false);rememberReading();if(readerOpen())closeQuestion({updateUrl:false,refresh:false});expandedLimit=60;render();window.scrollTo(0,0);openRouteQuestion();});
 render();openRouteQuestion();if('serviceWorker'in navigator&&!location.search.includes('android=1'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
